#!/usr/bin/env python3
"""Generator economy ledger for #1973 — counts only, research-only."""

from __future__ import annotations

import csv
import io
from pathlib import Path

# Proven selector family from #1961 / #1975 evidence (mechanism share).
CAR_CDR_DESCENDANTS = (
    "caar",  # 1010
    "cadr",  # 1011
    "cdar",  # 1100
    "cddr",  # 1101
    "caaar",  # deeper optional — still generated by same 2 actions
    "cadddr",  # deeper optional
)

# Bounded set used in first #1973 ledger (6 generated paths).
BOUNDED_SIX = ("caar", "cadr", "cdar", "cddr", "caaar", "caddr")


def economy(rows_avoided: int, rule_count: int) -> float:
    return rows_avoided / max(rule_count, 1)


def main() -> None:
    rows = [
        {
            "candidate": "flat_explicit_rows",
            "rule_count": 0,
            "descendants_generated": 0,
            "rows_avoided": 0,
            "explicit_rows_needed": len(BOUNDED_SIX),
            "economy_ratio": 0.0,
            "admission": "donor_baseline",
        },
        {
            "candidate": "CAR_CDR_suffix_0_1",
            "rule_count": 2,
            "descendants_generated": len(BOUNDED_SIX),
            "rows_avoided": len(BOUNDED_SIX),
            "explicit_rows_needed": 2,  # two roots; descendants via suffix
            "economy_ratio": economy(len(BOUNDED_SIX), 2),
            "admission": "pass_economy_and_semantic",
        },
        {
            "candidate": "one_off_ATOM_NULL_style",
            "rule_count": 1,
            "descendants_generated": 1,
            "rows_avoided": 1,
            "explicit_rows_needed": 1,
            "economy_ratio": economy(1, 1),
            "admission": "semantic_maybe_economy_weak",
        },
    ]

    buf = io.StringIO()
    w = csv.DictWriter(
        buf,
        fieldnames=list(rows[0].keys()),
        delimiter="\t",
        lineterminator="\n",
    )
    w.writeheader()
    w.writerows(rows)
    text = buf.getvalue()
    print(text)

    out = Path("docs/research/1973-generator-economy.tsv")
    if Path("docs/research").is_dir():
        out.write_text(text, encoding="utf-8")
        print(f"wrote {out}", flush=True)


if __name__ == "__main__":
    main()
